import java.util.*;interface PaymentMethod{boolean processPayment(double amount);}class CreditCardPayment implements PaymentMethod{public boolean processPayment(double a){return a>0;}}class PayPalPayment implements PaymentMethod{boolean success;PayPalPayment(boolean s){success=s;}public boolean processPayment(double a){return success&&a>0;}}class BankTransferPayment implements PaymentMethod{public boolean processPayment(double a){return a>0;}}class Customer{String name;Customer(String n){name=n;}}class Product{String name;double price;int qty;Product(String n,double p,int q){name=n;price=p;qty=q;}}class Order{Customer customer;List<Product> items=new ArrayList<>();String status="Pending";Order(Customer c){customer=c;}void add(Product p){if(p.qty>0)items.add(p);}double total(){double t=0;for(Product p:items)t+=p.price*p.qty;return t;}boolean pay(PaymentMethod p){if(items.isEmpty())return false;if(p.processPayment(total())){status="Paid";return true;}return false;}}public class Main{public static void main(String[]a){}}